face.layout_source:
// spectral-vocoder.face: the panel for tap/examples/spectral/spectral-vocoder.tap.
//
// Only layout lives here.  The style is a theme from face/themes, chosen per
// family in face/themes/families.json:
//
//   facec face/themes/<theme>.face tap/examples/spectral/spectral-vocoder.face --meta <graph>.cragmeta

face "Spectral Vocoder" {
  row(gap = 10) {
    box "Vocoder" { knob.big "Depth" (depth) knob "Release" (release) }
    box "Out" { knob "Gain" (gain) }
    viz(grow = 1)
  }
}
